  { transform: 'scaleY(0.8) scaleX(1.1)', cursor: 'grabbing' },

  { transform: 'scaleY(1) scaleX(1)' },

];

const timing = {

  duration: 120,

  iterations: 1,

  composite: 'replace',

};

