For anyone with tampermonkey, this userscript fixes the issue temporarily.

```

// ==UserScript==

// @name         Fix broken vrchat groups

// @version      0.1

// @description  Yes

// @match        https://vrchat.com/*

// @run-at       document-start

// @grant        unsafeWindow

// ==/UserScript==

(function() {

    'use strict';

    const originalFetch = unsafeWindow.fetch;

    unsafeWindow.fetch = async (...args) => {

        let res = await originalFetch(...args);

        function patchJson(data) {

            if (data.myMember && data.myMember.roleIds && data.roles) {

                data.myMember.roleIds = data.myMember.roleIds.filter(roleId => data.roles.some(role => role.id == roleId));

            }

            return data;

        }

        const oldJson = res.json.bind(res);

        res.json = () => oldJson().then(patchJson);

        if (res.headers.get('Content-Type').includes('application/json')) {

            const oldText = res.text.bind(res);

            res.text = () => oldText().then((data) => {

                return JSON.stringify(patchJson(JSON.parse(data)))

            });

        }

        return res;

    };

})();

```

